def group_messages(apps, schema_editor):
    """
    پیش از این هر والد با هر فرزند یک گفت‌وگوی پیوسته داشت؛ همان یک گفت‌وگو می‌شود (عنوان = اولین پرسش).
    """
    Message = apps.get_model("ai", "AssistantMessage")
    Conversation = apps.get_model("ai", "AssistantConversation")
    # order_by() خالی: بی‌آن ترتیبِ پیش‌فرضِ مدل (created_at) واردِ DISTINCT می‌شود و هر پیام یک «جفت» می‌شد
    pairs = set(Message.objects.filter(conversation__isnull=True).order_by()
                .values_list("parent_id", "child_id").distinct())
    for parent_id, child_id in pairs:
        rows = Message.objects.filter(parent_id=parent_id, child_id=child_id, conversation__isnull=True)
        first = rows.filter(role="user").order_by("created_at", "id").first()
        last = rows.order_by("-created_at", "-id").first()
        if last is None:
            continue
        title = " ".join((first.content if first else "").split())
        if len(title) > 60:
            title = title[:59].rstrip() + "…"
        conversation = Conversation.objects.create(parent_id=parent_id, child_id=child_id, title=title)
        rows.update(conversation=conversation)
        Conversation.objects.filter(pk=conversation.pk).update(created_at=first.created_at if first else last.created_at,
                                                               updated_at=last.created_at)


